function catmullPoint(p0,p1,p2,p3,t,tau) {
  const s=(1-tau)/2, t2=t*t, t3=t2*t;
  const m1={x:(p2.x-p0.x)*s, y:(p2.y-p0.y)*s};
  const m2={x:(p3.x-p1.x)*s, y:(p3.y-p1.y)*s};
  const h00=2*t3-3*t2+1, h10=t3-2*t2+t;
  const h01=-2*t3+3*t2, h11=t3-t2;
  return {
    x:h00*p1.x+h10*m1.x+h01*p2.x+h11*m2.x,
    y:h00*p1.y+h10*m1.y+h01*p2.y+h11*m2.y
  };
}
